  "Sẵn sàng buông câu": "Ready to Cast",
  "Dừng con lăn đúng ô vàng nhỏ ở giữa thanh.": "Stop the marker inside the small gold zone at the center of the meter.",
  "Canh đúng ô vàng để câu cá": "Stop in the Gold Zone to Catch a Fish",
  "Mỗi lượt, con lăn đi hết sang trái rồi trở lại phải một lần. Bấm": "Each turn, the marker moves all the way left, then back to the right once. Press",
  "Dừng": "Stop",
  "trong ô vàng giữa thanh mới câu được cá.": "while it is in the gold zone at the center to catch a fish.",
  "Chờ cá cắn…": "Waiting for a bite…",
  "Dừng đúng ô vàng · Mỗi lượt chỉ bấm một lần · Sai hoặc hết lượt là trượt": "Stop in the gold zone · Press only once per turn · Missing the zone or running out of time loses the catch",
