  "Bật chuyển động pháo hoa": "Play the fireworks animation",
  "Chúc nàng năm mới an khang, mọi điều mong ước đều thành sự thật.": "May the new year bring you peace and health, and may all your wishes come true.",
  "Mong một năm mới bình an, lòng luôn nhẹ nhõm như gió xuân.": "May the year ahead be peaceful, and your heart as light as the spring breeze.",
  "Chúc nàng tài hoa thêm rạng rỡ, phúc lành luôn ghé cửa.": "May your talents shine ever brighter, and blessings always find your door.",
  "Mong những chuyện buồn ở lại năm cũ, từ nay chỉ đón tin vui.": "May your sorrows remain in the old year, and only glad tidings find you now.",
