  "Khi đi cùng: thế mạng cho chủ 1 lần khi gặp cái chết; thú cưng sẽ biến mất. Không hóa giải kết thúc xuất cung hay lãnh cung cả đời.": "While accompanying you: saves you from death once, then disappears. Does not prevent endings caused by leaving the palace or lifelong Cold Palace confinement.",
  "Khi đi cùng: xác suất thụ thai +⟦0⟧ điểm phần trăm (từ 18 tuổi).": "While accompanying you: increases the chance of conception by ⟦0⟧ percentage points from age 18.",
  "Khi đi cùng lúc sinh: tăng cơ hội con có tư chất từ Ưu tú trở lên thêm ⟦0⟧ điểm phần trăm.": "When present at childbirth: increases the chance of a child with Outstanding aptitude or higher by ⟦0⟧ percentage points.",
  "Lần đầu nhận nuôi: thiện cảm với mọi NPC đang sống +⟦0⟧.": "When first adopted: Affection with every living NPC +⟦0⟧.",
  "Khi đi cùng: được miễn án lãnh cung mới. Không gỡ án đang thi hành hoặc án tranh hậu thất bại.": "While accompanying you: prevents new Cold Palace sentences. Does not lift an existing sentence or one imposed after a failed bid for the Empress's throne.",
