  "Phiên bản phẩm vị không hợp lệ.": "Invalid court rank data version.",
  "Bộ nhớ thiết bị đầy · Cần kết nối để lưu thành tích": "Device storage is full · Connect to save your achievements",
  "Chơi vô danh · Thành tích đã lưu online": "Playing as a guest · Achievements saved online",
  "Thành tích chờ kết nối · Tiến trình vẫn trên máy": "Achievements awaiting connection · Progress remains on this device",
  "Chỉ nhân vật trên 18 tuổi (từ 18 tuổi 1 tháng) được vào BXH.": "Only characters older than 18 (at least 18 years and 1 month) may enter the leaderboards.",
