  "Nàng được phong ⟦0⟧, nhận bộ y phục theo cấp mới.": "You are invested as ⟦0⟧ and receive attire befitting your new rank.",
  "Thi họa đạt ⟦0⟧ điểm": "Painting score: ⟦0⟧ points",
  "⟦0⟧ Hoàng Thái Hậu": "Empress Dowager ⟦0⟧",
  "⟦0⟧ Nàng suy kiệt, không qua khỏi biến cố bị tỷ muội hãm hại.": "⟦0⟧ Exhausted beyond recovery, you succumb to your sworn sister's betrayal.",
  "⟦0⟧ · Bạn": "⟦0⟧ · You",
  "Hạng ⟦0⟧": "Place ⟦0⟧",
  ", cài ⟦0⟧": ", adorned with ⟦0⟧",
  ", ⟦0⟧ bạc": ", ⟦0⟧ silver",
